    @php
        $chartCeiling = max(48, ceil(max((float) $metricHistory->max('average_cycle'), $averageTarget) / 12) * 12);
        $chartPoints = $metricHistory->values()->map(function ($metric, $index) use ($metricHistory, $chartCeiling) {
            $x = $metricHistory->count() > 1 ? $index * 600 / ($metricHistory->count() - 1) : 300;
            $y = 170 - ((float) $metric->average_cycle / $chartCeiling * 158);
            return round($x, 1).','.round($y, 1);
        })->implode(' ');
        $chartLinePath = 'M '.str_replace(' ', ' L ', $chartPoints);
        $chartStartX = $metricHistory->count() > 1 ? 0 : 300;
        $chartEndX = $metricHistory->count() > 1 ? 600 : 300;
        $chartAreaPath = $chartPoints ? $chartLinePath.' L '.$chartEndX.' 170 L '.$chartStartX.' 170 Z' : '';
        $chartTargetY = 170 - ($averageTarget / $chartCeiling * 158);
    @endphp
